class Index(object):
    FIRST = 0
    LAST = -1


class KPI(object):
    def __init__(
        self,
        start_point,
        end_point,
        technologies=None,
        start_search_after=None,
        requirement=None,
        should_contain_rst_event=False,
        multi_indication=False,
        device_info_event=None,
        check_hwf=False,
        min_start_and_end_point_offset=0,
        min_offset_between_indication_points=0,
        required_alarms=None,
        name=None,
        normalize_runtime_view=False,
        **kwargs,
    ):
        """

        :param Union[CellEvent] start_point: Start Point for calculating KPI
        :param Union[CellEvent] end_point: End Point for calculating KPI
        :param List[GSM, WCDMA, LTE, NR] technologies: list of technology to check
        :param requirement: TBD
        :param should_contain_rst_event: True/False RST event occurred when site reset is performed.
        :param multi_indication: True/False, Allow multi indications occurs before start point.
        :param device_info_event: ChangeEvent for get device info.
        :param check_hwf: True/False, Enable HWF detection - at this moment applicable only for KPI1.
        :param min_start_and_end_point_offset: offset in seconds between start and end point entries.
        :param min_offset_between_indication_points: minimum offset between indication points - it helps ignore
        potential new indication points which in reality belongs to the same operation(eg when start_search_after
        :param required_alarms - list of required alarms which should occurs after operation(all endpoint are ignored
        till all defined alarms appear)
        contains a few regex).
        :param normalize_runtime_view: True/False, Normalize dist_name by removing RUNTIME_VIEW segment for matching
        cells between start and end points (useful when RUNTIME_VIEW changes during operation).
        """
        self.name = type(self).__name__ if name is None else name
        self.start_point = start_point
        self.end_point = end_point
        self.technologies = technologies if technologies else (GSM, WCDMA, LTE, NR)
        self.start_search_after = start_search_after
        self.should_contain_rst_event = should_contain_rst_event
        self.min_start_and_end_point_offset = datetime.timedelta(seconds=min_start_and_end_point_offset)
        self.min_offset_between_indication_points = datetime.timedelta(seconds=min_offset_between_indication_points)
        self.required_alarms = required_alarms
        self.multi_indication = multi_indication
        self.device_info_event = device_info_event
        self.requirement = requirement
        self.hwf_detection = HWFDetection() if check_hwf else None
        self.normalize_runtime_view = normalize_runtime_view

        self.current_iteration = SingleKPIIterationResults(required_alarms=required_alarms)
        self.iteration_results = []
        self.exception_msg = []

    def _build_start_point_event(self):
        # Not used at this moment please check:
        # https://wrgitlab.ext.net.nokia.com/TAF/taf.ul.oam_kpi_calculations/-/merge_requests/109
        logging.debug("Building start point event")

    def add_debug_indication_entry(self, dist_name, value, timestamp):
        self.current_iteration.debug_indication_point.append(
            {"timestamp": timestamp, "dist_name": dist_name, "value": value}
        )

    def add_indication_entry(self, dist_name, value, timestamp, mrbts_id=None):  # noqa: C901
        self.current_iteration.indication_point.append({"timestamp": timestamp, "dist_name": dist_name, "value": value})

        if mrbts_id:
            self.set_operation_triggered_from_if_not_defined(operation_triggered_from=mrbts_id)
        if self.start_point is None:
            self._build_start_point_event()

        try:
            if isinstance(value, dict):
                device_dist_name = None
                if "targetDN" in value:
                    device_dist_name = value["targetDN"]
                elif re.search(DistNamePatterns.RMOD_L_INFO, dist_name):
                    device_dist_name = dist_name
                elif re.search(DistNamePatterns.RMOD_INFO, dist_name):
                    device_dist_name = dist_name
                if device_dist_name:
                    self.current_iteration.device_info_event = ChangeEvent(
                        index=Index.FIRST, status=[], pattern=r"^{}$".format(device_dist_name)
                    )
        except KeyError:
            pass

    def set_operation_triggered_from_if_not_defined(self, operation_triggered_from):
        if not self.current_iteration.operation_triggered_from:
            logging.debug("Operation triggered from: {}".format(operation_triggered_from))
            self.current_iteration.operation_triggered_from = operation_triggered_from

    def add_alarms_before_iteration(self, active_alarms):
        for alarm in active_alarms:
            simplified_dict = alarm.to_simplified_dict()
            self.current_iteration.alarms["before"].append(simplified_dict)

    def add_additional_alarms_during_iteration(self, alarms_during_iteration):
        for alarm in alarms_during_iteration:
            simplified_dict = alarm.to_simplified_dict()
            simplified_dict_copy = copy.copy(simplified_dict)
            if "alarm_removed_timestamp" in simplified_dict_copy:
                del simplified_dict_copy["alarm_removed_timestamp"]
            if simplified_dict_copy not in self.current_iteration.alarms["before"]:
                self.current_iteration.alarms["additional_alarms_during_iteration"].append(simplified_dict)

    def add_alarms_after_iteration(self, active_alarms):
        for alarm in active_alarms:
            simplified_dict = alarm.to_simplified_dict()
            self.current_iteration.alarms["after"].append(simplified_dict)
        for alarm_info in self.current_iteration.alarms["after"]:
            if alarm_info not in self.current_iteration.alarms["before"]:
                self.current_iteration.alarms["diff_after_before"].append(alarm_info)

    def add_device_info(self, dist_name, value):
        try:
            self.current_iteration.device_info["product_name"] = value["productName"].split(" ")[0]
            self.current_iteration.device_info["serial_number"] = value["serialNumber"]
            self.current_iteration.device_info["product_code"] = value["productCode"]
            self.current_iteration.device_info["dist_name"] = dist_name
        except KeyError:
            pass

    def add_start_entry(self, technology, dist_name, timestamp, value=None, mrbts_id=None, mrbts_ids=None):
        r"""
        Add results to start_point_entries
        :param str technology: Used technology: GSM/WCDMA/LTE/NR
        :param str dist_name: full object dist_name
        :param datetime timestamp: datetime timestamp
        :param dict value: value of the entry
        :param str mrbts_id: MRBTS-\d+
        :param set mrbts_ids: list of all mrbts_ids eg: {MRBTS-1, MRBTS-2}
        :return: None
        """
        self._add_start_entry(self.current_iteration, technology, dist_name, timestamp, value)
        if mrbts_id:
            self.set_operation_triggered_from_if_not_defined(operation_triggered_from=mrbts_id)
        if mrbts_ids and len(mrbts_ids) > 1:
            mrbts_ids_needing_start_points = mrbts_ids if technology == "COMMON" else [mrbts_id]
            for _mrbts_id in mrbts_ids_needing_start_points:
                if _mrbts_id not in self.current_iteration.bts_detailed_results:
                    self.current_iteration.bts_detailed_results[_mrbts_id] = SingleKPIIterationResults()
                self._add_start_entry(
                    self.current_iteration.bts_detailed_results[_mrbts_id], technology, dist_name, timestamp, value
                )

    def _add_start_entry(self, iteration, technology, dist_name, timestamp, value=None):
        """
        Add results to start_point_entries
        :param str technology: Used technology: GSM/WCDMA/LTE/NR
        :param str dist_name: full object dist_name
        :param datetime timestamp: datetime timestamp
        :param dict value: value of the entry
        :return: None
        """
        # Use normalized dist_name as key if normalize_runtime_view is enabled
        key_dist_name = self._normalize_dist_name(dist_name) if self.normalize_runtime_view else dist_name

        if technology not in iteration.start_point_entries:
            iteration.start_point_entries[technology] = OrderedDict()
        if key_dist_name not in iteration.start_point_entries[technology]:
            iteration.start_point_entries[technology][key_dist_name] = []
        iteration.start_point_entries[technology][key_dist_name].append(timestamp)

        # Store normalized dist_name in detected_cell_dist_names if normalize_runtime_view is enabled
        if is_cell_dist_name(dist_name):
            iteration.detected_cell_dist_names.add(key_dist_name)
        if value and "targetDN" in value and is_cell_dist_name(value["targetDN"]):
            target_dn_to_store = (
                self._normalize_dist_name(value["targetDN"]) if self.normalize_runtime_view else value["targetDN"]
            )
            iteration.detected_cell_dist_names.add(target_dn_to_store)

    def add_end_entry(self, technology, dist_name, timestamp, mrbts_id=None, mrbts_ids=None):
        r"""
        Add results to end_point_entries
        :param str technology: Used technology: GSM/WCDMA/LTE/NR
        :param str dist_name: full object dist_name
        :param datetime timestamp: datetime timestamp
        :param str mrbts_id: MRBTS-\d+
        :param set mrbts_ids: list of all mrbts_ids eg: {MRBTS-1, MRBTS-2}
        :return: None
        """
        self._add_end_entry(self.current_iteration, technology, dist_name, timestamp)
        if mrbts_id:
            self.set_operation_triggered_from_if_not_defined(operation_triggered_from=mrbts_id)
            if mrbts_ids and len(mrbts_ids) > 1:
                mrbts_ids_needing_end_points = mrbts_ids if technology == "COMMON" else [mrbts_id]
                for _mrbts_id in mrbts_ids_needing_end_points:
                    self._add_end_entry(
                        self.current_iteration.bts_detailed_results[_mrbts_id], technology, dist_name, timestamp
                    )

    def _add_end_entry(self, iteration, technology, dist_name, timestamp):
        """
        Add results to end_point_entries
        :param str technology: Used technology: GSM/WCDMA/LTE/NR
        :param str dist_name: full object dist_name
        :param datetime timestamp: datetime timestamp
        :return: None
        """
        # Use normalized dist_name as key if normalize_runtime_view is enabled
        key_dist_name = self._normalize_dist_name(dist_name) if self.normalize_runtime_view else dist_name

        if technology not in iteration.end_point_entries:
            iteration.end_point_entries[technology] = OrderedDict()
        if key_dist_name not in iteration.end_point_entries[technology]:
            iteration.end_point_entries[technology][key_dist_name] = []
        iteration.end_point_entries[technology][key_dist_name].append(timestamp)

    def propagate_start_point_timestamp_for_all_mrbts(self, mrbts_ids):
        if mrbts_ids and len(mrbts_ids) > 1:
            bts_results = self.current_iteration.bts_detailed_results
            for mrbts_id in mrbts_ids:
                if mrbts_id not in bts_results:
                    bts_results[mrbts_id] = SingleKPIIterationResults()
                bts_results[mrbts_id].start_point_timestamp = self.current_iteration.start_point_timestamp

    def calculate_delta(self):
        """
        Calculate delta between start_point and end_point entries.
        :return: None
        """

        self._validate_entries()
        self._calculate_delta(self.current_iteration)

        if self.current_iteration.bts_detailed_results:
            skipped_btss = []
            for bts_name, bts_iteration in self.current_iteration.bts_detailed_results.items():
                if not bts_iteration.end_point_entries and (
                    "COMMON" in bts_iteration.start_point_entries or bts_iteration.start_point_timestamp
                ):
                    logging.debug("Skip calculating delta for {} ".format(bts_name))
                    skipped_btss.append(bts_name)
                    continue
                self._calculate_delta(bts_iteration)
            for bts_name in skipped_btss:
                del self.current_iteration.bts_detailed_results[bts_name]

    def _calculate_delta(self, iteration):  # noqa: C901
        start_point = None
        end_point = None
        first_cell_down = None
        last_cell_down = None
        first_cell_up = None
        last_cell_up = None

        for technology_name in iteration.end_point_entries:
            if isinstance(self.start_point, (SiteResetRequest, datetime.datetime)):
                tech_start_point = iteration.start_point_timestamp
                start_point = iteration.start_point_timestamp
            elif technology_name not in iteration.start_point_entries:
                if len(iteration.start_point_entries) == 1 and "COMMON" in iteration.start_point_entries:
                    tech_start_point = list(iteration.start_point_entries["COMMON"].values())[0][0]
                    start_point = tech_start_point
                else:
                    raise StartPointDataNotAvailable(self, ", RAT: {}".format(technology_name))
            else:
                start_points_values = list(iteration.start_point_entries[technology_name].values())
                start_points_keys = list(iteration.start_point_entries[technology_name].keys())
                tech_start_point = start_points_values[self.start_point.index][0]
                start_point_method = min if self.start_point.index == 0 else max
                start_point = (
                    tech_start_point if start_point is None else start_point_method(start_point, tech_start_point)
                )
                if technology_name not in ["COMMON", None] and is_cell_dist_name(start_points_keys[0]):
                    if first_cell_down is None or start_points_values[0][0] < first_cell_down["timestamp"]:
                        first_cell_down = {"timestamp": start_points_values[0][0], "dist_name": start_points_keys[0]}
                    if last_cell_down is None or start_points_values[-1][0] > last_cell_down["timestamp"]:
                        last_cell_down = {"timestamp": start_points_values[-1][0], "dist_name": start_points_keys[-1]}

            end_points_values = list(iteration.end_point_entries[technology_name].values())
            end_points_keys = list(iteration.end_point_entries[technology_name].keys())
            tech_end_point = end_points_values[self.end_point.index][0]
            iteration.detailed_results[technology_name] = {
                "start_point": tech_start_point,
                "end_point": tech_end_point,
                "delta": tech_end_point - tech_start_point,
            }

            end_point_method = min if self.end_point.index == 0 else max
            end_point = tech_end_point if end_point is None else end_point_method(end_point, tech_end_point)

            if technology_name not in ["COMMON", None] and is_cell_dist_name(end_points_keys[0]):
                if first_cell_up is None or end_points_values[0][0] < first_cell_up["timestamp"]:
                    first_cell_up = {"timestamp": end_points_values[0][0], "dist_name": end_points_keys[0]}
                if last_cell_up is None or end_points_values[-1][0] > last_cell_up["timestamp"]:
                    last_cell_up = {"timestamp": end_points_values[-1][0], "dist_name": end_points_keys[-1]}

        if iteration.detected_cell_dist_names:
            # detected_cell_dist_names already contains normalized names if normalize_runtime_view is enabled
            # Keys in start_point_entries and end_point_entries are also normalized
            for dist_name in iteration.detected_cell_dist_names:
                cell_start_point = self._get_timestamp_for_dist_name(dist_name, iteration.start_point_entries)
                cell_end_point = self._get_timestamp_for_dist_name(dist_name, iteration.end_point_entries)
                if cell_start_point:
                    iteration.cell_detailed_results[dist_name] = {
                        "start_point": cell_start_point,
                        "end_point": cell_end_point,
                        "delta": cell_end_point - cell_start_point if cell_end_point else None,
                    }

        # It's WA when cell down is not visible for all cells(before RST event)
        if (
            self.should_contain_rst_event
            and iteration.site_reset_timestamp
            and start_point > iteration.site_reset_timestamp
            and hasattr(self.start_point, "index")
            and self.start_point.index == Index.LAST
        ):
            start_point = iteration.site_reset_timestamp

        iteration.start_point_timestamp = start_point
        iteration.end_point_timestamp = end_point
        iteration.delta = end_point - start_point
        iteration.first_cell_down = first_cell_down
        iteration.last_cell_down = last_cell_down
        iteration.first_cell_up = first_cell_up
        iteration.last_cell_up = last_cell_up

        if self.hwf_detection:
            iteration.hwf = self.hwf_detection.get_results()

    def check_interval(self, max_interval_ms=550):
        interval = int(self.current_iteration.min_ims_record_interval * 1000)
        logging.debug("Interval between IMS records is set to {} ms".format(interval))
        if interval > max_interval_ms:
            logging.warning(
                "Interval between IMS records is {} ms. Please set lower value (at least 500ms) during"
                " 'setup_admin' connection ('update_interval' param)"
                " Thanks that your results will be more precise".format(interval)
            )

    @staticmethod
    def _get_timestamp_for_dist_name(dist_name, entry_point):
        """
        Get first timestamp for dist_name from entry_point.
        Note: dist_name should already be normalized if normalize_runtime_view is enabled,
        as keys in entry_point are already normalized.
        :param str dist_name: dist_name (already normalized if normalize_runtime_view is enabled)
        :param dict entry_point: Entry point dictionary (keys are already normalized if normalize_runtime_view is enabled)
        :return datetime: First timestamp or None
        """
        for rat in entry_point:
            if dist_name in entry_point[rat]:
                values = entry_point[rat][dist_name]
                if values:
                    return values[0]
        return None

    def save_current_iteration(self):
        """
        Save results from single iteration.
        :return: None
        """

        self.iteration_results.append(self.current_iteration.to_dict())

    def _validate_entries(self, ignore_number_of_dist_names=False):  # noqa: C901
        if self.start_search_after and not self.current_iteration.indication_point:
            raise IndicationPointDataNotAvailable(self)
        self._validate_rst_event()
        if not self.current_iteration.start_point_entries and not self.current_iteration.end_point_entries:
            raise DataNotAvailable(r"StartPoint and EndPoint data not available for KPI_NAME: {}".format(self.name))
        self._validate_endpoints()
        if not self.current_iteration.start_point_entries:
            raise StartPointDataNotAvailable(self)
        if ignore_number_of_dist_names is False:
            if not self.check_if_number_of_dist_names_in_start_points_and_end_points_are_the_same():
                raise DataNotAvailable(
                    r"Number of dist names detected in EndPoints is different than "
                    "in StartPoints for KPI_NAME: {}".format(self.name)
                )

    def _validate_rst_event(self):
        if self.should_contain_rst_event and not self.current_iteration.site_reset_timestamp:
            raise DataNotAvailable(r"RST (Site Reset) event not available for KPI_NAME: {}".format(self.name))

    def _validate_endpoints(self):
        if not self.current_iteration.end_point_entries:
            raise EndPointDataNotAvailable(self)

    def _validate_indication_and_end_points(self):
        if not self.check_if_number_of_indication_points_and_end_points_are_the_same():
            raise DataNotAvailable(
                "Number of dist names detected in Indication Points is different than "
                "in EndPoints for KPI_NAME: {}".format(self.name)
            )

    def check_if_number_of_dist_names_in_start_points_and_end_points_are_the_same(self):

        if "COMMON" in self.current_iteration.start_point_entries:
            return False

        number_of_start_point_entries = len(self._get_list_of_entries(self.current_iteration.start_point_entries))
        number_of_end_point_entries = len(self._get_list_of_entries(self.current_iteration.end_point_entries))

        if number_of_start_point_entries > 0 and number_of_start_point_entries == number_of_end_point_entries:
            return True

        return False

    def check_if_number_of_indication_points_and_end_points_are_the_same(self):
        number_of_indication_points = len(self.current_iteration.indication_point)
        number_of_end_point_entries = len(self._get_list_of_entries(self.current_iteration.end_point_entries))

        if number_of_indication_points > 0 and number_of_indication_points == number_of_end_point_entries:
            return True

        return False

    def _normalize_dist_name(self, dist_name):
        """
        Normalize dist_name by removing RUNTIME_VIEW and MRBTS_R segments if normalize_runtime_view is enabled.
        This allows matching cells that have different RUNTIME_VIEW and MRBTS_R values (e.g., during role switchover).
        :param str dist_name: Original dist_name
        :return str: Normalized dist_name
        """
        if self.normalize_runtime_view:
            # Use normalize_dist_name from utilities to normalize dist_name
            normalized = normalize_dist_name(dist_name)
            return normalized
        return dist_name

    def _get_list_of_entries(self, entry_point):
        set_of_entries = set()
        for rat in entry_point:
            for dist_name in entry_point[rat]:
                normalized_name = self._normalize_dist_name(dist_name)
                set_of_entries.add(normalized_name)
        return set_of_entries


class KPISWDL(object):
    def __init__(self, start_point, end_point, name=None):
        self.name = type(self).__name__ if name is None else name
        self.start_point = start_point
        self.end_point = end_point
        self.results = []


class KPISOAP(object):
    class KPIResult(object):
        def __init__(self, required_alarms=None):

            self._initialize_variables()

        def clear_result(self):
            """
            Clear variables.
            :return: None
            """
            self._initialize_variables()

        def _initialize_variables(self):
            """
            Clear variables.
            :return: None
            """
            self.start_point_entries = {}
            self.end_point_entries = {}
            self.delta = None
            self.start_point_timestamp = None
            self.end_point_timestamp = None
            self.device_info = {}
            self.entity_id = None

        def to_dict(self):
            """
            Returns class variables as a dictionary.
            Uses deepcopy for dict fields to prevent issues from later mutation.
            """
            import copy
            return {
                "start_point_timestamp": self.start_point_timestamp,
                "end_point_timestamp": self.end_point_timestamp,
                "delta": self.delta,
                "entity_id": self.entity_id,
                "start_points": copy.deepcopy(self.start_point_entries),
                "end_points": copy.deepcopy(self.end_point_entries),
                "device_info": copy.deepcopy(self.device_info),
            }

    class Point(object):
        def __init__(self, index, parser_function, parser_kwargs=None):
            self.index = index
            self.parser_function = parser_function
            self.parser_kwargs = {} if parser_kwargs is None else parser_kwargs

    def __init__(self, start_point: Point, end_point: Point, name=None):
        self.name = type(self).__name__ if name is None else name
        self.start_point = start_point
        self.end_point = end_point
        self.current_result = self.KPIResult()
        self.dict_results = {}
        self.results = []


class HWFDetection(object):
    def __init__(self):
        self.swconfig_pattern = re.compile(DistNamePatterns.SWCONFIG)
        self.rmod_pattern = re.compile(DistNamePatterns.RMOD_L_INFO)
        self._results = []

    def search_hwf_entry(self, dist_name, value):
        if self.swconfig_pattern.search(dist_name):
            hwf = self._get_hwf_from_swconfig(value)
        elif self.rmod_pattern.search(dist_name):
            hwf = self._get_hwf_from_rmod(value)
        else:
            hwf = None
        if hwf is not None:
            logging.debug("[HWF]\n\tDist Name:\t{}\n\tValue:\t\t{}\n".format(dist_name, hwf))
            self._results.append({"dist_name": dist_name, "value": value, "hwf": hwf})

    def get_results(self):
        hwf = [record["hwf"] for record in self._results]
        all_status = all(hwf)
        any_status = any(hwf)
        statuses_should_be_the_same = all_status is any_status
        if statuses_should_be_the_same or not hwf:
            final_status = all_status if hwf else False
            logging.debug("[HWF]\n\tFinal HWF Value:\t{}".format(final_status))
            return {"value": final_status, "details": self._results}
        else:
            logging.debug("There is inconsistent in HWF detection. Please check details: {}".format(self._results))
            logging.warning(
                "There is inconsistent in HWF detection. Please check simplified results: {}".format(
                    self.get_simplified_results()
                )
            )
            return {"value": None, "details": self._results}

    def get_simplified_results(self):  # noqa: C901
        simplified_results = []

        def get_flag_value(record):
            for flag_record in record["value"]["appliedConfiguration"]:
                if flag_record["flag"] == "0x4f0214":
                    return flag_record["value"]
            return None

        for record in self._results:
            data = {"dist_name": record["dist_name"], "hwf": record["hwf"]}
            if self.rmod_pattern.search(record["dist_name"]):
                data["availability_status"] = record["value"]["stateInfo"]["availabilityStatus"]
                data["procedural_state"] = record["value"]["stateInfo"]["proceduralState"]
            elif self.swconfig_pattern.search(record["dist_name"]):
                data["0x4f0214"] = get_flag_value(record)

            simplified_results.append(data)
        return simplified_results

    def clear_results(self):
        self._results = []

    @staticmethod
    def _get_hwf_from_swconfig(value):
        for record in value["appliedConfiguration"]:
            if record["flag"] == "0x4f0214":
                if record["value"] == "0x0":
                    return False
        return True

    @staticmethod
    def _get_hwf_from_rmod(value):
        if value["stateInfo"]["availabilityStatus"] == "NotInstalled":
            if value["stateInfo"]["proceduralState"] == "fromHWF":
                return True
            return False


class SingleKPIIterationResults(object):
    def __init__(self, required_alarms=None):

        self._initialize_variables()
        self.required_alarms = copy.copy(required_alarms) if required_alarms else None
        self._required_alarms = required_alarms

    def clear_current_iteration_results(self):
        """
        Clear variables.
        :return: None
        """
        self._initialize_variables()
        self.required_alarms = copy.copy(self._required_alarms) if self._required_alarms else None

    def _initialize_variables(self):
        """
        Clear variables.
        :return: None
        """
        self.first_start_point_entry_timestamp = None
        self.start_point_entries = {}
        self.end_point_entries = {}
        self.delta = None
        self.start_point_timestamp = None
        self.end_point_timestamp = None
        self.detailed_results = {}
        self.cell_detailed_results = {}
        self.site_reset_timestamp = None
        self.indication_point = []
        self.debug_indication_point = []
        self.device_info = {}
        self.device_info_event = None
        self.hwf = {}
        self.detected_cell_dist_names = set()
        self.min_ims_record_interval = None
        self.alarms = {
            "before": [],
            "additional_alarms_during_iteration": [],
            "after": [],
            "diff_after_before": [],
        }
        self.bts_detailed_results = {}
        self.operation_triggered_from = None
        self.first_cell_down = None
        self.last_cell_down = None
        self.first_cell_up = None
        self.last_cell_up = None

    def is_iteration_started(self):
        if self.start_point_entries or self.end_point_entries or self.start_point_timestamp or self.indication_point:
            return True
        return False

    def to_dict(self, main=True):  # noqa: C901
        """
        Return representative of Iteration object to dict
        :return: alarm_dict
        """
        summary = {
            "start_point_timestamp": self.start_point_timestamp,
            "end_point_timestamp": self.end_point_timestamp,
            "delta": self.delta,
            "start_points": self.start_point_entries,
            "end_points": self.end_point_entries,
            "detailed_results": self.detailed_results,
        }

        if main:
            summary["site_reset_timestamp"] = self.site_reset_timestamp
            summary["indication_point"] = self.indication_point
            summary["device_info"] = self.device_info
            summary["alarms"] = self.alarms
            if self.hwf:
                summary["hwf"] = self.hwf

        for param in [
            "site_reset_timestamp",
            "indication_point",
            "cell_detailed_results",
            "operation_triggered_from",
            "first_cell_down",
            "last_cell_down",
            "first_cell_up",
            "last_cell_up",
        ]:
            value = getattr(self, param)
            if value:
                summary[param] = value

        if self.bts_detailed_results.items():
            summary["bts_detailed_results"] = {}
            for bts_name, bts_results in self.bts_detailed_results.items():
                summary["bts_detailed_results"][bts_name] = bts_results.to_dict(main=False)

        return summary


def append_status_with_degraded_if_serial_console_connected(cls):
    def _modify_init(original_init):
        def new_init(self, **kwargs):
            serial_console_connected = kwargs.pop("serial_console_connected", False)
            original_init(self, **kwargs)
            if serial_console_connected:
                if self.end_point.status[0] == CellStatuses.UNLOCKED_CELL:
                    new_status = CellStatuses.UNLOCKED_DEGRADED_CELL
                else:
                    new_status = CellStatuses.DEGRADED
                if new_status not in self.end_point.status:
                    self.end_point.status.append(new_status)

        return new_init

    cls.__init__ = _modify_init(cls.__init__)
    return cls


def replace_pattern_if_cell_dist_names_defined(replace_start_point=True, replace_end_point=True):  # noqa: C901
    def decorator(cls):
        def _modify_init(original_init):
            def new_init(self, **kwargs):
                cell_dist_names = kwargs.pop("cell_dist_names", None)
                original_init(self, **kwargs)
                if cell_dist_names is not None:
                    dn_pattern = r"$|".join(cell_dist_names) + r"$"
                    if replace_start_point:
                        self.start_point.pattern = dn_pattern
                        self.start_point.compiled_pattern = re.compile(dn_pattern)
                    if replace_end_point:
                        self.end_point.pattern = dn_pattern
                        self.end_point.compiled_pattern = re.compile(dn_pattern)

            return new_init

        cls.__init__ = _modify_init(cls.__init__)
        return cls

    return decorator


