class BaseKPI17(KPI):
    @staticmethod
    def _get_proper_patterns(global_cell_id, dist_name):
        request_status = copy.deepcopy(CellStatuses.BLOCK_UNBLOCK_REQUEST)
        if dist_name:
            dist_name_pattern = r"{}$".format(dist_name)
            request_status["targetDN"].value = dist_name_pattern
            end_point_pattern = dist_name_pattern
        else:
            request_status["targetDN"].value = CellStatuses.BLOCK_UNBLOCK_REQUEST["targetDN"].value.format(
                global_cell_id=global_cell_id
            )
            end_point_pattern = DistNamePatterns.SINGLE_CELL_INFO.format(global_cell_id=global_cell_id)
        return request_status, end_point_pattern


class KPI17a(BaseKPI17):
    def __init__(self, global_cell_id=r"\d+", dist_name=None, **kwargs):
        block_request_status, end_point_pattern = self._get_proper_patterns(global_cell_id, dist_name)

        super(KPI17a, self).__init__(
            start_point=ChangeEvent(
                index=Index.FIRST, status=block_request_status, pattern=DistNamePatterns.BLOCK_CELL_REQUEST
            ),
            end_point=ChangeEvent(index=Index.FIRST, status=CellStatuses.BLOCKED_CELL, pattern=end_point_pattern),
            **kwargs,
        )


class KPI17b(BaseKPI17):
    def __init__(self, global_cell_id=r"\d+", dist_name=None, **kwargs):
        unblock_request_status, end_point_pattern = self._get_proper_patterns(global_cell_id, dist_name)
        unblocked_status = CellStatuses.UNBLOCKED_CELL
        if dist_name and GSM.CELL_NAME in dist_name:
            unblocked_status = CellStatuses.UNBLOCKED_CELL_ONLINE_OR_DEGRADED

        origin_start_point = ChangeEvent(
            index=Index.FIRST,
            status=unblock_request_status,
            pattern=DistNamePatterns.UNBLOCK_CELL_REQUEST,
            entry_type="updates",
        )

        if isinstance(try_to_int(global_cell_id), int) or dist_name is not None:
            start_point = origin_start_point
        else:
            start_point = OneOfEvents(
                events=[
                    origin_start_point,
                    AnyStatus(index=Index.FIRST, pattern=DistNamePatterns.UNBLOCK_CELL_REQUEST, entry_type="removals"),
                ],
                index=Index.FIRST,
            )

        super(KPI17b, self).__init__(
            start_point=start_point,
            end_point=ChangeEvent(index=Index.FIRST, status=unblocked_status, pattern=end_point_pattern),
            **kwargs,
        )

    def _validate_entries(self):
        super(KPI17b, self)._validate_entries(ignore_number_of_dist_names=True)


