class BaseKPI51(KPI):
    @staticmethod
    def _get_proper_patterns(triggered_from=None, ims_from=None):
        status = RMODStatuses.RMOD_RESET
        pattern = DistNamePatterns.RESET_IND

        if ims_from and triggered_from:
            logging.warning(
                "'triggered_from' and 'ims_from' parameters are deprecated and will be deleted "
                "in the future. Please use new solution with 'merge_ims_files' parameter."
            )
            if ims_from.lower() in ["primary", "secondary"] and triggered_from.lower() in ["primary", "secondary"]:
                if ims_from.lower() != triggered_from.lower():
                    status = RMODStatuses.DOWN
                    pattern = DistNamePatterns.RMOD_INFO
            else:
                raise ValueError("'ims_from' and 'triggered_from' param values " "must be 'primary' or 'secondary'")

        return status, pattern


