class KPI55d(KPI):
    def __init__(self, cell_dist_names, technologies=None):
        super(KPI55d, self).__init__(
            start_search_after=ChangeEvent(
                index=Index.FIRST,
                status=SiteStatuses.SW_ACTIVATION_WITH_AUTOMATIC_ACTIVATION,
                pattern=DistNamePatterns.SW_UPDATE_IND,
            ),
            start_point=self._build_all_events_list(
                cell_dist_names=cell_dist_names, index=Index.FIRST, status=[CellStatuses.DOWN, CellStatuses.DEGRADED]
            ),
            end_point=self._build_all_events_list(
                cell_dist_names=cell_dist_names, index=Index.LAST, status=CellStatuses.UP
            ),
            technologies=technologies,
        )

    @staticmethod
    def _build_all_events_list(cell_dist_names, index, status):
        cells_dn = set(cell_dist_names)
        events = set()
        for cell_dn in cells_dn:
            events.add(ChangeEvent(index=index, status=status, pattern=r"^{}$".format(cell_dn)))
        return AllEvents(index=index, events=events)


